from __future__ import annotations

import unicodedata


def normalize_key(s: str) -> str:
    return unicodedata.normalize("NFC", s)

from __future__ import annotations

__all__ = ["Ledger", "ConflictError"]


class ConflictError(Exception):
    pass


class Ledger:
    def __init__(self, path: str) -> None:
        self._path = path

from __future__ import annotations

import argparse
import sys


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="ledgerlock",
        description="Append-only tamper-evident key/value ledger.",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    verify = subparsers.add_parser("verify", help="verify a ledger JSONL file")
    verify.add_argument("ledger", help="path to the ledger JSONL file")

    snapshot = subparsers.add_parser("snapshot", help="emit deterministic snapshot of a ledger")
    snapshot.add_argument("ledger", help="path to the ledger JSONL file")
    snapshot.add_argument("--out", help="output file (default: stdout)")

    apply = subparsers.add_parser("apply", help="apply an atomic batch to a ledger")
    apply.add_argument("ledger", help="path to the ledger JSONL file")
    apply.add_argument("--batch", required=True, help="path to the batch JSON file")

    repair_tail = subparsers.add_parser(
        "repair-tail", help="rewrite a ledger with a truncated tail line removed"
    )
    repair_tail.add_argument("ledger", help="path to the ledger JSONL file")

    args = parser.parse_args(argv)

    if args.command == "verify":
        from ledgerlock import ledger as _ledger

        return _ledger.verify(args.ledger)
    if args.command == "snapshot":
        from ledgerlock import ledger as _ledger

        return _ledger.snapshot(args.ledger, args.out)
    if args.command == "apply":
        from ledgerlock import ledger as _ledger

        return _ledger.apply_batch(args.ledger, args.batch)
    if args.command == "repair-tail":
        from ledgerlock import ledger as _ledger

        return _ledger.repair_tail(args.ledger)

    parser.error(f"unknown command: {args.command}")
    return 2


if __name__ == "__main__":
    sys.exit(main())

